import{_ as r,c as a,o as i,a2 as n}from"./chunks/framework.mqLGQ42V.js";const k=JSON.parse('{"title":"分享链接概览 (Share Links Overview) - Rive 编辑器","description":"编辑器 (Editor) 分享链接是一种快速、无需代码的方法，可以让你的 Rive 文件在网站上运行，或向客户展示你的图形作品。","frontmatter":{"title":"分享链接概览 (Share Links Overview) - Rive 编辑器","description":"编辑器 (Editor) 分享链接是一种快速、无需代码的方法，可以让你的 Rive 文件在网站上运行，或向客户展示你的图形作品。","head":[["meta",{"name":"keywords","content":"Rive, Rive 中文文档, Rive 编辑器, 分享链接概览"}]]},"headers":[],"relativePath":"editor/share-links.md","filePath":"editor/share-links.md","lastUpdated":1774867914000}'),o={name:"editor/share-links.md"};function t(l,e,s,h,p,g){return i(),a("div",null,[...e[0]||(e[0]=[n('<p>编辑器 (Editor)</p><h1 id="分享链接概览-share-links-overview" tabindex="-1">分享链接概览 (Share Links Overview) <a class="header-anchor" href="#分享链接概览-share-links-overview" aria-label="Permalink to &quot;分享链接概览 (Share Links Overview)&quot;">​</a></h1><p>分享链接是一种快速、无需代码的方法，可以让你的 Rive 文件在网站上运行，或向客户展示你的图形作品。</p><p>生成分享链接功能适用于 Voyager 和 Enterprise 方案。<a href="https://rive.app/pricing" target="_blank" rel="noreferrer">了解更多关于我们的方案和定价的信息</a>。</p><p>通过分享链接分享你当前处理的文件版本。请注意，这并不等同于让某人访问包含所有版本历史记录的实时文件。分享链接是文件当前状态的“冻结”版本。如果你对文件进行了更改，则需要生成一个新的分享链接。</p><p>某些功能（如 <a href="https://rive.app/blog/introducing-vector-feathering" target="_blank" rel="noreferrer">矢量羽化</a>）仅通过 Rive 渲染器 (Rive Renderer) 支持。更多信息请参阅我们的 <a href="/docs/feature-support">功能支持</a> 页面。</p><h2 id="​-创建分享链接-creating-a-share-link" tabindex="-1"><a href="#creating-a-share-link">​</a> 创建分享链接 (Creating a share link) <a class="header-anchor" href="#​-创建分享链接-creating-a-share-link" aria-label="Permalink to &quot;[​](#creating-a-share-link) 创建分享链接 (Creating a share link)&quot;">​</a></h2><p>你可以从“导出 (Export)”菜单生成分享链接。该链接可以分享给任何人，而不仅仅是你的团队成员。</p><blockquote><p><em>[原文档演示图由于官方服务器迁移已失效]</em> (描述: 创建分享链接示例) 在分享链接弹窗中，选择你想要分享的画板、动画或状态机。 <em>[原文档演示图由于官方服务器迁移已失效]</em> (描述: 分享链接选项选择)</p></blockquote><h3 id="​-分享链接选项-share-link-options" tabindex="-1"><a href="#share-link-options">​</a> 分享链接选项 (Share link options) <a class="header-anchor" href="#​-分享链接选项-share-link-options" aria-label="Permalink to &quot;[​](#share-link-options) 分享链接选项 (Share link options)&quot;">​</a></h3><p>点击“Generate link”按钮后，会出现几种分享链接类型：</p><ul><li><strong>Share link (分享链接)</strong>：在 Rive 网站的一个唯一 URL 上展示，带有边框。适用于快速向客户展示 Rive 作品。</li><li><strong>Embed link (嵌入链接)</strong>：独立显示你的 Rive 作品，不带边框。适用于将作品嵌入 Notion、Tome、Telegram 等支持“预览展开 (unfurling)”的第三方平台。</li><li><strong>Embed code (嵌入代码)</strong>：一段 iframe 代码片段。适用于 Webflow、WordPress 等可以编辑 HTML 的平台，无需配置 Web 运行时即可快速部署。</li><li><strong>Framer code (已弃用)</strong>：请参阅新的官方 <a href="https://www.framer.com/marketplace/plugins/rive/" target="_blank" rel="noreferrer">Rive Framer 插件</a>。</li></ul><p>其他选项包括：</p><ul><li><strong>Enable (启用)</strong>：关闭开关可防止他人查看该链接。</li><li><strong>Rive Renderer</strong>：在使用 Rive 渲染器（推荐）和 Canvas 渲染器之间切换。</li></ul><h2 id="​-平台集成-integrations" tabindex="-1"><a href="#integrations">​</a> 平台集成 (Integrations) <a class="header-anchor" href="#​-平台集成-integrations" aria-label="Permalink to &quot;[​](#integrations) 平台集成 (Integrations)&quot;">​</a></h2><p>使用分享链接将你的 Rive 文件嵌入到其他知名工具和平台中。</p><h3 id="​-notion" tabindex="-1"><a href="#notion">​</a> Notion <a class="header-anchor" href="#​-notion" aria-label="Permalink to &quot;[​](#notion) Notion&quot;">​</a></h3><ol><li>复制 <strong>Share link</strong> 或 <strong>Embed link</strong>。</li><li>在 Notion 中粘贴链接。</li><li>在菜单中选择 <strong>Embed</strong> 选项。</li></ol><blockquote><p><em>[原文档演示图由于官方服务器迁移已失效]</em> (描述: Notion 嵌入示例)</p></blockquote><h3 id="​-webflow" tabindex="-1"><a href="#webflow">​</a> Webflow <a class="header-anchor" href="#​-webflow" aria-label="Permalink to &quot;[​](#webflow) Webflow&quot;">​</a></h3><ol><li>复制带有 iframe 的 <strong>Embed code</strong>。</li><li>在 Webflow 中添加一个 <strong>Embed</strong> 组件以访问 HTML 编辑器。</li><li>粘贴从 Rive 编辑器复制的代码。</li></ol><blockquote><p><em>[原文档演示图由于官方服务器迁移已失效]</em> (描述: Webflow 嵌入示例)</p></blockquote><h3 id="​-tome" tabindex="-1"><a href="#tome">​</a> Tome <a class="header-anchor" href="#​-tome" aria-label="Permalink to &quot;[​](#tome) Tome&quot;">​</a></h3><ol><li>复制 <strong>Embed link</strong>。</li><li>在 Tome 幻灯片上添加一个 <strong>Weblink</strong>。</li><li>粘贴链接。</li></ol><h2 id="​-管理分享链接-managing-share-links" tabindex="-1"><a href="#managing-share-links">​</a> 管理分享链接 (Managing share links) <a class="header-anchor" href="#​-管理分享链接-managing-share-links" aria-label="Permalink to &quot;[​](#managing-share-links) 管理分享链接 (Managing share links)&quot;">​</a></h2><p>访问设置中的 <a href="https://rive.app/profile/?section=share%20links" target="_blank" rel="noreferrer">Share Links</a> 部分来管理你生成的链接。你可以通过关闭 <strong>Active</strong> 开关来禁用链接。</p><p><a href="https://help.rive.app/editor/exporting/exporting-for-backup" target="_blank" rel="noreferrer">导出为备份</a><a href="https://help.rive.app/editor/share-links/framer-and-rive" target="_blank" rel="noreferrer">Framer 与 Rive</a></p>',27)])])}const m=r(o,[["render",t]]);export{k as __pageData,m as default};
